import{_ as e,c as a,o as r,af as n}from"./chunks/framework.4G89wRmb.js";const m=JSON.parse('{"title":"南武进步者大会制度","description":"","frontmatter":{},"headers":[],"relativePath":"databank/settings/main/nambu_congress.md","filePath":"databank/settings/main/nambu_congress.md"}'),l={name:"databank/settings/main/nambu_congress.md"};function s(o,t,i,g,h,d){return r(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="南武进步者大会制度" tabindex="-1">南武进步者大会制度 <a class="header-anchor" href="#南武进步者大会制度" aria-label="Permalink to “南武进步者大会制度”">​</a></h1><p><strong>南武进步者大会制度</strong>是<a href="./rengoist_republic_of_nambu.html">联合主义南武共和国</a>的根本政治制度，是国家一切权力的来源与体现。它是一个自下而上选举产生、自上而下进行指导的代议机关体系，确保了<a href="./nambu_rengoist_party.html">南武联合党</a>的领导核心地位与广大人民行使国家权力的有机统一。该体系的最高机关为<strong>全南武进步者大会</strong>。</p><h2 id="基本情报" tabindex="-1">基本情报 <a class="header-anchor" href="#基本情报" aria-label="Permalink to “基本情报”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">項目</th><th style="text-align:left;">内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>制度名称</strong></td><td style="text-align:left;">南武进步者大会制度（Nambu Progressors Congress of System）</td></tr><tr><td style="text-align:left;"><strong>性质</strong></td><td style="text-align:left;">国家根本政治制度、代议机关体系</td></tr><tr><td style="text-align:left;"><strong>最高机关</strong></td><td style="text-align:left;">全南武进步者大会（Whole-Nambu Progressors Congress）</td></tr><tr><td style="text-align:left;"><strong>领导核心</strong></td><td style="text-align:left;"><a href="./nambu_rengoist_party.html">南武联合党</a></td></tr><tr><td style="text-align:left;"><strong>任期</strong></td><td style="text-align:left;">全国及地方各级均为八年</td></tr><tr><td style="text-align:left;"><strong>俗称</strong></td><td style="text-align:left;">进步会、八年会（指代各级进步者大会，尤其特指全南武进步者大会）</td></tr></tbody></table><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to “概要”">​</a></h2><p>进步者大会制度是<a href="./rengoism.html">联合主义</a>国家学说的核心支柱。它规定，国家的一切权力属于人民，人民通过选举代表组成各级进步者大会来行使国家权力。最高权力机关是<strong>全南武进步者大会</strong>，在全国范围内行使立法、决定、任免和监督等最高职权。地方各级进步者大会则是本行政区域内的权力机关，负责处理地方事务并对本级人民政府实行监督。</p><p>该制度并非西方议会式的权力分立，而是在<a href="./nambu_rengoist_party.html">南武联合党</a>的集中统一领导下，确保国家机器高效运转的民主集中制体现。</p><h2 id="历史沿革" tabindex="-1">历史沿革 <a class="header-anchor" href="#历史沿革" aria-label="Permalink to “历史沿革”">​</a></h2><p>进步者大会制度的雏形源于<a href="./../others/progressive_revolution.html">南武进步革命</a>时期建立的工人、农民和士兵代表会议。革命胜利后，为了将这种直接的革命民主形式制度化、规范化，国父<a href="./../people/nambu_kojun.html">南武香淳</a>亲自构想了这一体系。</p><p>随着1999年<a href="./rengoist_republic_of_nambu.html">联合主义南武共和国</a>成立，进步者大会制度被正式载入国家宪法，成为国家的根本政治制度。其<strong>八年一届</strong>的会期，旨在确保国家长期战略的稳定性和政策制定的前瞻性，因此也被民间俗称为“<strong>八年会</strong>”。</p><h2 id="组织体系" tabindex="-1">组织体系 <a class="header-anchor" href="#组织体系" aria-label="Permalink to “组织体系”">​</a></h2><p>进步者大会制度按行政区划分为全国和地方两个层级，构成一个完整的金字塔式权力结构。</p><ol><li><p><strong>全南武进步者大会</strong> 位于体系顶端，是唯一的国家级立法机关和最高权力机关。其代表由各道、都、府、县级进步者大会和人民防卫军选举产生。</p></li><li><p><strong>地方各级进步者大会</strong> 包括<strong>道、都、府、县</strong>级和<strong>市、町、村</strong>级进步者大会。它们是地方国家权力机关，负责：</p><ul><li>保证宪法和法律在本行政区域的遵守和执行。</li><li>制定和决定本地区的重大事项。</li><li>选举产生本级人民政府的领导人。</li><li>选举上一级进步者大会的代表。</li></ul></li></ol><h2 id="职权与运作" tabindex="-1">职权与运作 <a class="header-anchor" href="#职权与运作" aria-label="Permalink to “职权与运作”">​</a></h2><p>各级进步者大会的核心职权包括：</p><ul><li><p><strong>立法权</strong><strong>全南武进步者大会</strong>拥有修改国家宪法、制定和修改国家基本法律的专属权力。地方进步者大会则可以在不与上级法律抵触的前提下，制定地方性法规。</p></li><li><p><strong>决定权</strong> 审查和批准国民经济和社会发展计划（如五年计划）、国家预算与决算。对战争与和平等国家最重大的问题作出决定。</p></li><li><p><strong>任免权</strong> 这是其最核心的权力之一。<strong>全南武进步者大会</strong>选举并有权罢免：</p><ul><li><a href="./supreme_peoples_committee.html">南武最高人民委员会</a>的核心成员。</li><li><a href="./../main/central_government.html">南武中央人民政府</a>的首相及其他组成人员。</li><li>国家最高司法和监察机关的负责人。 地方各级进步者大会则选举并罢免本级政府及相应机关的领导人。</li></ul></li><li><p><strong>监督权</strong> 监督本级人民政府、法院等国家机关的工作。听取和审议其工作报告，确保其行为符合人民的利益和党的路线。</p></li></ul><p>所有议案和决策，均在<a href="./nambu_rengoist_party.html">南武联合党</a>的指导下，由全体代表通过民主投票方式决定，体现了民主集中制的原则。</p>',17)])])}const _=e(l,[["render",s]]);export{m as __pageData,_ as default};
